#!/usr/bin/env python3
"""
Deeb Life OS — self-extracting setup script.

Run:  python setup_deeb_life_os.py

Creates the full deeb-life-agent/ project (27 files) in the current directory.
"""
import base64, json
from pathlib import Path

# All 27 project files, base64-encoded
FILES = '''{
  ".env.example": "",
  "ai_brain.py": "",
  "calendar_manager.py": "",
  "config.py": "",
  "database.py": "",
  "main.py": "",
  "memory/adaptation_log.md": "",
  "memory/ai_income_rules.md": "",
  "memory/behavior_patterns.md": "",
  "memory/coaching_rules.md": "",
  "memory/diet_rules.md": "",
  "memory/energy_rules.md": "",
  "memory/goals.md": "",
  "memory/job_search_rules.md": "",
  "memory/user_profile.md": "",
  "memory/workout_rules.md": "",
  "prompts/adaptation_prompt.md": "",
  "prompts/daily_planner.md": "",
  "prompts/evening_review.md": "",
  "prompts/journaling_prompt.md": "",
  "prompts/morning_checkin.md": "",
  "prompts/post_task_check.md": "",
  "prompts/pre_task_check.md": "",
  "prompts/weekly_review.md": "",
  "requirements.txt": "",
  "scheduler.py": "",
  "telegram_bot.py": ""
}'''


def main():
    data = json.loads(FILES)
    base = Path("deeb-life-agent")
    (base / "data").mkdir(parents=True, exist_ok=True)
    (base / "memory").mkdir(parents=True, exist_ok=True)
    (base / "prompts").mkdir(parents=True, exist_ok=True)
    for rel_path, b64_content in data.items():
        target = base / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(base64.b64decode(b64_content))
        print(f"  created  {target}")
    print(f"\n✓ {len(data)} files extracted to deeb-life-agent/")
    print("\nNext steps:")
    print("  1. cd deeb-life-agent")
    print("  2. cp .env.example .env  && fill in your credentials")
    print("  3. pip install -r requirements.txt")
    print("  4. python main.py")


if __name__ == "__main__":
    main()
